(14, 1, 1, '3', 'GIFTCODE OPEN BETA LÀNG LÁ TRUYỀN KỲ', 'GIFTCODE OPEN BETA LÀNG LÁ TRUYỀN KỲ', '<!DOCTYPE html>\r\n<html lang=\"en\">\r\n<head>\r\n    <meta charset=\"UTF-8\">\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n    <style>\r\n        .post {\r\n            font-family: Arial, sans-serif;\r\n            border: 1px solid #ddd;\r\n            padding: 20px;\r\n            margin: 20px auto;\r\n            max-width: 600px;\r\n            box-shadow: 0 0 10px rgba(0, 0, 0, 0.1);\r\n            background-color: #f9f9f9;\r\n        }\r\n        .post-header {\r\n            text-align: center;\r\n            margin-bottom: 20px;\r\n        }\r\n        .post-header h2 {\r\n            margin: 0;\r\n            color: #333;\r\n        }\r\n        .post-body {\r\n            line-height: 1.6;\r\n        }\r\n        .post-body ul {\r\n            list-style-type: none;\r\n            padding: 0;\r\n        }\r\n        .post-body ul li {\r\n            margin-bottom: 10px;\r\n            font-weight: bold;\r\n            color: #555;\r\n        }\r\n        .post-footer {\r\n            text-align: center;\r\n            margin-top: 20px;\r\n            font-size: 0.9em;\r\n            color: #777;\r\n        }\r\n        .note {\r\n            margin-top: 20px;\r\n            padding: 10px;\r\n            background-color: #fff3cd;\r\n            border: 1px solid #ffeeba;\r\n            color: #856404;\r\n            font-size: 0.9em;\r\n            line-height: 1.4;\r\n        }\r\n    </style>\r\n</head>\r\n<body>\r\n<div class=\"post\">\r\n    <div class=\"post-header\">\r\n        <h2>GIFTCODE LÀNG LÁ TRUYỀN KỲ</h2>\r\n    </div>\r\n    <div class=\"post-body\">\r\n        <ul>\r\n            <li>GIFTCODE: langlatruyenky</li>\r\n            <li>GIFTCODE: tanthu</li>\r\n<li>GIFTCODE: truyenkyno1</li>\r\n<li>GIFTCODE: baotri1808</li>\r\n        </ul>\r\n        <div class=\"note\">\r\n            <strong>Lưu ý:</strong> Nhập giftcode tại phần cài đặt, quà tặng. Mỗi giftcode chỉ dùng được 1 lần. Nếu không thấy mục quà tặng, thì tắt game vô lại.\r\n            Anh em tham gia box Zalo, tích cực xem live của admin sẽ được thêm code riêng\r\n            CODE FAN CỨNG SẼ ĐƯỢC PHÁT HẰNG TUẦN ĐỐI VỚI NHỮNG NHÂN VẬT CÓ TƯƠNG TÁC FAN CỨNG TẠI FANPAGE VÀ BOX ZALO!.\r\n        </div>\r\n    </div>\r\n    <div class=\"post-footer mt-2\"></div>\r\n</div>\r\n</body>\r\n</html>\r\n', '', 897, 0, NULL, NULL),
(15, 1, 1, '4', 'ĐUA TOP CAO THỦ LÀNG LÁ TRUYỀN KỲ', 'ĐUA TOP CAO THỦ LÀNG LÁ TRUYỀN KỲ', '<!DOCTYPE html>\r\n<html lang=\"en\">\r\n<head>\r\n    <meta charset=\"UTF-8\">\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n    <style>\r\n        body {\r\n            font-family: Arial, sans-serif;\r\n            background-color: #f2f2f2;\r\n            margin: 0;\r\n            padding: 0;\r\n            display: flex;\r\n            justify-content: center;\r\n            align-items: center;\r\n            height: 100vh;\r\n        }\r\n        .post {\r\n            border: 1px solid #ddd;\r\n            padding: 20px;\r\n            margin: 20px auto;\r\n            max-width: 600px;\r\n            box-shadow: 0 0 10px rgba(0, 0, 0, 0.1);\r\n            background-color: #ffffff;\r\n            border-radius: 10px;\r\n        }\r\n        .post-header {\r\n            text-align: center;\r\n            margin-bottom: 20px;\r\n        }\r\n        .post-header h2 {\r\n            margin: 0;\r\n            color: #333;\r\n            font-size: 24px;\r\n        }\r\n        .post-body {\r\n            line-height: 1.8;\r\n        }\r\n        .post-body ul {\r\n            list-style-type: none;\r\n            padding: 0;\r\n        }\r\n        .post-body ul li {\r\n            margin-bottom: 10px;\r\n        }\r\n        .post-body ul li strong {\r\n            display: block;\r\n            color: #333;\r\n            margin-bottom: 5px;\r\n        }\r\n        .highlight {\r\n            color: #ff0000;\r\n            font-weight: bold;\r\n        }\r\n    </style>\r\n</head>\r\n<body>\r\n<div class=\"post\">\r\n    <div class=\"post-header\">\r\n        <h2>PHẦN THƯỞNG ĐUA TOP CAO THỦ</h2>\r\n    </div>\r\n    <div class=\"post-body\">\r\n        <ul>\r\n            <li><strong>Thời gian đua top:</strong> 19H 15/08/2024 đến 23H59 01/09/2024</li>\r\n            <li><strong>Phần Thưởng Theo BXH Top 1-10:</strong></li>\r\n            <ul>\r\n                <li>\r\n                    <strong>Top 1:</strong>\r\n                    Danh Hiệu Vô Song Làng Lá Truyền Kỳ<br>\r\n                    Thông báo độc quyền khi đăng nhập<br>\r\n                    Set trang Bị Hokage Cấp 50 Tự Chọn Hệ Max Option<br>\r\n                    Cải Trang Lục Đạo Tự Chọn Vĩnh Viễn<br>\r\n                    400000 vàng\r\n                </li>\r\n                <li>\r\n                    <strong>Top 2:</strong>\r\n                    Danh Hiệu Chí Tôn Làng Lá Truyền Kỳ<br>\r\n                    Set trang Bị Hokage Cấp 50 Tự Chọn Hệ Max Option<br>\r\n                    Cải Trang Lục Đạo Tự Chọn Vĩnh Viễn<br>\r\n                    250000 vàng\r\n                </li>\r\n                <li>\r\n                    <strong>Top 3:</strong>\r\n                    Danh Hiệu Chí Tôn Làng Lá Truyền Kỳ<br>\r\n                    Set trang Bị Hokage Cấp 50 Tự Chọn Hệ Ngẫu Nhiên Option<br>\r\n                    Cải Trang Lục Đạo Tự Chọn Vĩnh Viễn<br>\r\n                    150000 vàng\r\n                </li>\r\n                <li>\r\n                    <strong>Top 4-10:</strong>\r\n                    Set trang Bị Hokage Cấp 50 Tự Chọn Hệ Ngẫu Nhiên Option<br>\r\n                    Cải Trang Giáo Viên Tự Chọn Vĩnh Viễn<br>\r\n                    50000 vàng\r\n                </li>\r\n            </ul>\r\n            <li><strong class=\"highlight\">Cải Trang Lục Đạo tự chọn bao gồm:</strong> Kakashi Lục Đạo, Obito Lục Đạo, Madara Lục Đạo</li>\r\n            <li><strong class=\"highlight\">TOP 1 được tự chọn:</strong> Kakashi Lục Đạo, Obito Lục Đạo, Madara Lục Đạo</li>\r\n            <li><strong class=\"highlight\">TOP 2, 3 được tự chọn:</strong> Kakashi Lục Đạo, Obito Lục Đạo</li>\r\n            <li><strong class=\"highlight\">Quà Top sẽ trao từ 2-3 ngày sau khi công bố kết quả từ ADMIN</strong></li>\r\n            <li><strong class=\"highlight\">Quà Top có thể chậm hơn dự kiến nếu có sự cố phát sinh. Mong các nhẫn giả thông cảm!</strong></li>\r\n        </ul>\r\n    </div>\r\n</div>\r\n</body>\r\n</html>\r\n', '', 1612, 0, NULL, NULL),
(16, 1, 1, '5', 'ĐUA TOP TÀI PHÚ LÀNG LÁ TRUYỀN KỲ', 'ĐUA TOP TÀI PHÚ LÀNG LÁ TRUYỀN KỲ', '<!DOCTYPE html>\r\n<html lang=\"en\">\r\n<head>\r\n    <meta charset=\"UTF-8\">\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n    <style>\r\n        body {\r\n            font-family: Arial, sans-serif;\r\n            background-color: #f2f2f2;\r\n            margin: 0;\r\n            padding: 0;\r\n            display: flex;\r\n            justify-content: center;\r\n            align-items: center;\r\n            height: 100vh;\r\n        }\r\n        .post {\r\n            border: 1px solid #ddd;\r\n            padding: 20px;\r\n            margin: 20px auto;\r\n            max-width: 600px;\r\n            box-shadow: 0 0 10px rgba(0, 0, 0, 0.1);\r\n            background-color: #ffffff;\r\n            border-radius: 10px;\r\n        }\r\n        .post-header {\r\n            text-align: center;\r\n            margin-bottom: 20px;\r\n        }\r\n        .post-header h2 {\r\n            margin: 0;\r\n            color: #333;\r\n            font-size: 24px;\r\n        }\r\n        .post-body {\r\n            line-height: 1.8;\r\n        }\r\n        .post-body ul {\r\n            list-style-type: none;\r\n            padding: 0;\r\n        }\r\n        .post-body ul li {\r\n            margin-bottom: 10px;\r\n        }\r\n        .post-body ul li strong {\r\n            display: block;\r\n            color: #333;\r\n            margin-bottom: 5px;\r\n        }\r\n        .highlight {\r\n            color: #ff0000;\r\n            font-weight: bold;\r\n        }\r\n    </style>\r\n</head>\r\n<body>\r\n<div class=\"post\">\r\n    <div class=\"post-header\">\r\n        <h2>PHẦN THƯỞNG ĐUA TOP TÀI PHÚ</h2>\r\n    </div>\r\n    <div class=\"post-body\">\r\n        <ul>\r\n            <li><strong>Thời gian đua top:</strong> 19H 15/08/2024 đến 23H59 01/09/2024</li>\r\n            <li><strong>Phần Thưởng Theo BXH Top 1-10:</strong></li>\r\n            <ul>\r\n                <li>\r\n                    <strong>Top 1:</strong>\r\n                    Danh Hiệu Đại Gia Làng Lá Truyền Kỳ<br>\r\n                    Thông báo độc quyền khi đăng nhập<br>\r\n                    Thú Cưỡi Tự Chọn Vĩnh Viễn Max Option<br>\r\n                    x4 Siêu Bùa Nổ<br>\r\n                    300000 vàng\r\n                </li>\r\n                <li>\r\n                    <strong>Top 2:</strong>\r\n                    Danh Hiệu Giàu Có Làng Lá Truyền Kỳ<br>\r\n                    Thú Cưỡi Tự Chọn Vĩnh Viễn Max Option<br>\r\n                    x3 Siêu Bùa Nổ<br>\r\n                    150000 vàng\r\n                </li>\r\n                <li>\r\n                    <strong>Top 3:</strong>\r\n                    Danh Hiệu Giàu Có Làng Lá Truyền Kỳ<br>\r\n                    Thú Cưỡi Tự Chọn Vĩnh Viễn Max Option<br>\r\n                    x2 Siêu Bùa Nổ<br>\r\n                    100000 vàng\r\n                </li>\r\n                <li>\r\n                    <strong>Top 4-10:</strong>\r\n                    Thú Cưỡi Ngẫu Nhiên Random Option<br>\r\n                    x1 Siêu Bùa Nổ<br>\r\n                    50000 vàng\r\n                </li>\r\n            </ul>\r\n            <li><strong class=\"highlight\">Thú Cưỡi bao gồm:</strong> Phượng Hoàng Lửa, Ngựa Sắt, Tuần Lộc</li>\r\n            <li><strong class=\"highlight\">Quà Top sẽ trao từ 2-3 ngày sau khi công bố kết quả từ ADMIN</strong></li>\r\n            <li><strong class=\"highlight\">Quà Top có thể chậm hơn dự kiến nếu có sự cố phát sinh. Mong các nhẫn giả thông cảm!</strong></li>\r\n        </ul>\r\n    </div>\r\n</div>\r\n</body>\r\n</html>\r\n', '', 980, 0, NULL, NULL),
(17, 1, 1, '6', 'ĐUA TOP GIA TỘC LÀNG LÁ TRUYỀN KỲ', 'ĐUA TOP GIA TỘC LÀNG LÁ TRUYỀN KỲ', '<!DOCTYPE html>\n<html lang=\"en\">\n<head>\n    <meta charset=\"UTF-8\">\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\n    <style>\n        body {\n            font-family: Arial, sans-serif;\n            background-color: #f2f2f2;\n            margin: 0;\n            padding: 0;\n            display: flex;\n            justify-content: center;\n            align-items: center;\n            height: 100vh;\n        }\n        .post {\n            border: 1px solid #ddd;\n            padding: 20px;\n            margin: 20px auto;\n            max-width: 600px;\n            box-shadow: 0 0 10px rgba(0, 0, 0, 0.1);\n            background-color: #ffffff;\n            border-radius: 10px;\n        }\n        .post-header {\n            text-align: center;\n            margin-bottom: 20px;\n        }\n        .post-header h2 {\n            margin: 0;\n            color: #333;\n            font-size: 24px;\n        }\n        .post-body {\n            line-height: 1.8;\n        }\n        .post-body ul {\n            list-style-type: none;\n            padding: 0;\n        }\n        .post-body ul li {\n            margin-bottom: 10px;\n        }\n        .post-body ul li strong {\n            display: block;\n            color: #333;\n            margin-bottom: 5px;\n        }\n        .highlight {\n            color: #ff0000;\n            font-weight: bold;\n        }\n    </style>\n</head>\n<body>\n<div class=\"post\">\n    <div class=\"post-header\">\n        <h2>PHẦN THƯỞNG ĐUA TOP GIA TỘC</h2>\n    </div>\n    <div class=\"post-body\">\n        <ul>\n            <li><strong>Thời gian đua top:</strong> 19H 15/08/2024 đến 23H59 01/09/2024</li>\n            <li><strong>Phần Thưởng Theo BXH Top 1-10:</strong></li>\n            <ul>\n                <li>\n                    <strong>Top 1:</strong>\n                    x10 Danh Hiệu Gia Tộc Truyền Thuyết<br>\n                    x1 Cải Trang Hashirama<br>\n                    x15 Rương Cải Trang Tự Chọn<br>\n                    500.000.000 bạc<br>\n                    500000 vàng\n                </li>\n                <li>\n                    <strong>Top 2:</strong>\n                    x10 Rương Cải Trang Ngẫu Nhiên<br>\n                    250.000.000 bạc<br>\n                    250000 vàng\n                </li>\n                <li>\n                    <strong>Top 3:</strong>\n                    x5 Rương Cải Trang Ngẫu Nhiên<br>\n                    100.000.000 bạc<br>\n                    100000 vàng\n                </li>\n                <li>\n                    <strong>Top 4-5:</strong>\n                    50.000.000 bạc<br>\n                    50000 vàng\n                </li>\n            </ul>\n            <li><strong class=\"highlight\">Địa cung 5 Exp/1 người, Cấm thuật 5exp/1 người, Hoàn thành Ải gia tộc được 20 exp/1 người, tiêu diệt boss Ải gia tộc được 300Exp </strong></li>\n            <li><strong class=\"highlight\">Quà Top sẽ trao từ 2-3 ngày sau khi công bố kết quả từ ADMIN</strong></li>\n            <li><strong class=\"highlight\">Quà Top có thể chậm hơn dự kiến nếu có sự cố phát sinh. Mong các nhẫn giả thông cảm!</strong></li>\n        </ul>\n    </div>\n</div>\n</body>\n</html>\n', '', 739, 0, NULL, NULL),
(18, 1, 1, '7', 'ĐUA TOP CHUYÊN CẦN LÀNG LÁ TRUYỀN KỲ', 'ĐUA TOP CHUYÊN CẦN LÀNG LÁ TRUYỀN KỲ', '<!DOCTYPE html>\r\n<html lang=\"en\">\r\n<head>\r\n    <meta charset=\"UTF-8\">\r\n    <meta name=\"viewport\" content=\"width=device-width, initial-scale=1.0\">\r\n    <style>\r\n        body {\r\n            font-family: Arial, sans-serif;\r\n            background-color: #f2f2f2;\r\n            margin: 0;\r\n            padding: 0;\r\n            display: flex;\r\n            justify-content: center;\r\n            align-items: center;\r\n            height: 100vh;\r\n        }\r\n        .post {\r\n            border: 1px solid #ddd;\r\n            padding: 20px;\r\n            margin: 20px auto;\r\n            max-width: 600px;\r\n            box-shadow: 0 0 10px rgba(0, 0, 0, 0.1);\r\n            background-color: #ffffff;\r\n            border-radius: 10px;\r\n        }\r\n        .post-header {\r\n            text-align: center;\r\n            margin-bottom: 20px;\r\n        }\r\n        .post-header h2 {\r\n            margin: 0;\r\n            color: #333;\r\n            font-size: 24px;\r\n        }\r\n        .post-body {\r\n            line-height: 1.8;\r\n        }\r\n        .post-body ul {\r\n            list-style-type: none;\r\n            padding: 0;\r\n        }\r\n        .post-body ul li {\r\n            margin-bottom: 10px;\r\n        }\r\n        .post-body ul li strong {\r\n            display: block;\r\n            color: #333;\r\n            margin-bottom: 5px;\r\n        }\r\n        .highlight {\r\n            color: #ff0000;\r\n            font-weight: bold;\r\n        }\r\n    </style>\r\n</head>\r\n<body>\r\n<div class=\"post\">\r\n    <div class=\"post-header\">\r\n        <h2>PHẦN THƯỞNG ĐUA TOP CHUYÊN CẦN</h2>\r\n    </div>\r\n    <div class=\"post-body\">\r\n        <ul>\r\n            <li><strong>Thời gian đua top:</strong> 19H 15/08/2024 đến 23H59 01/09/2024</li>\r\n            <li><strong>Phần Thưởng Theo BXH Top 1-10:</strong>\r\n                <ul>\r\n                    <li>\r\n                        <strong>Top 1:</strong>\r\n                        Danh Hiệu Trùm Săn Boss<br>\r\n                        Cải Trang Giáo Viên Tự Chọn<br>\r\n                        100000 vàng\r\n                    </li>\r\n                    <li>\r\n                        <strong>Top 2:</strong>\r\n                        Danh Hiệu Cày Cuốc<br>\r\n                        Cải Trang Giáo Viên ngẫu nhiên<br>\r\n                        50000 vàng\r\n                    </li>\r\n                    <li>\r\n                        <strong>Top 3:</strong>\r\n                        Danh Hiệu Cày Cuốc<br>\r\n                        Cải Trang Giáo Viên ngẫu nhiên<br>\r\n                        50000 vàng\r\n                    </li>\r\n                    <li>\r\n                        <strong>Top 4-5:</strong>\r\n                        Cải Trang Giáo Viên ngẫu nhiên<br>\r\n                        20000 vàng\r\n                    </li>\r\n                </ul>\r\n            </li>\r\n            <li><strong class=\"highlight\">Điểm chuyên cần sẽ có được từ việc tham gia hoạt động địa cung, ải gia tộc, cấm thuật, săn boss vĩ thú, săn boss cao\r\n', '', 766, 0, NULL, NULL);

